/**************TEST CLASS DECLARATION*************/
@UnitTest
@ExtendWith(MockitoExtension.class)
 class PulsarModuleFactoryTest {}
/**************TEST METHOD BEGIN*************/
@Test
void shouldBuildModule(){
    when(dockerImages.get("apachepulsar/pulsar")).thenReturn(new DockerImageVersion("apachepulsar/pulsar", "1.1.1"));

    JHipsterModuleProperties properties = JHipsterModulesFixture.propertiesBuilder(TestFileUtils.tmpDirForTest())
      .basePackage("tech.jhipster.jhlitest")
      .build();

    JHipsterModule module = factory.buildModule(properties);

    assertThatModuleWithFiles(module, pomFile(), integrationTestAnnotation(), readmeFile())
      .hasFile("pom.xml")
      .containing(
        """
            <dependency>
              <groupId>org.springframework.boot</groupId>
              <artifactId>spring-boot-starter-pulsar</artifactId>
            </dependency>
        """
      )
      .containing(
        """
            <dependency>
              <groupId>org.testcontainers</groupId>
              <artifactId>pulsar</artifactId>
              <version>${testcontainers.version}</version>
              <scope>test</scope>
            </dependency>
        """
      )
      .and()
      .hasFile("src/main/docker/pulsar.yml")
      .containing("apachepulsar/pulsar:1.1.1")
      .and()
      .hasFile("src/main/resources/config/application.yml")
      .containing(
        """
        pulsar:
          client:
            service-url: pulsar://localhost:6650
        """
      )
      .and()
      .hasFile("src/test/resources/config/application-test.yml")
      .containing(
        """
        pulsar:
          client:
            num-io-threads: 8
          consumer:
            subscription-name: test-subscription
            topic-names[0]: test-topic
          producer:
            topic-name: test-topic
        """
      )
      .and()
      .hasJavaTests("tech/jhipster/jhlitest/PulsarTestContainerExtension.java")
      .hasFile("src/test/java/tech/jhipster/jhlitest/IntegrationTest.java")
      .containing("import org.junit.jupiter.api.extension.ExtendWith;")
      .containing("@ExtendWith(PulsarTestContainerExtension.class)")
      .and()
      .hasPrefixedFiles(
        "src/main/java/tech/jhipster/jhlitest/wire/pulsar/infrastructure/config",
        "PulsarProperties.java",
        "PulsarConfiguration.java"
      )
      .hasFiles("src/test/java/tech/jhipster/jhlitest/wire/pulsar/infrastructure/config/PulsarConfigurationIT.java")
      .hasFile("README.md")
      .containing(
        """
        ```bash
        docker compose -f src/main/docker/pulsar.yml up -d
        ```
        """
      );
  }
/**************TEST METHOD END*************/
/**************TEST HELPER METHOD BEGIN*************/
private ModuleFile integrationTestAnnotation(){
    return file("src/test/resources/projects/files/IntegrationTest.java", "src/test/java/tech/jhipster/jhlitest/IntegrationTest.java");
  }
public JHipsterModuleProperties build(){
            return new JHipsterModuleProperties(projectFolder, commitModules, properties);
        }
public JHipsterModulePropertiesBuilder basePackage(String basePackage){
            properties.put("packageName", basePackage);
            return this;
        }
public static JHipsterModulePropertiesBuilder propertiesBuilder(String projectFolder){
        return new JHipsterModulePropertiesBuilder(projectFolder);
    }
public static String tmpDirForTest(){
        return Path.of(tmpDir()).resolve("jhlite-test").resolve(UUID.randomUUID().toString()).toString().replace("\\", "/");
    }
public JHipsterModuleFileAsserter<JHipsterModuleAsserter> hasFile(String file){
            return new JHipsterModuleFileAsserter<>(this, projectFolder, file);
        }
public JHipsterModuleAsserter hasFiles(String... files){
            assertThat(files).as("Can't check null files for a module").isNotNull();
            SoftAssertions assertions = new SoftAssertions();
            Stream.of(files).map(projectFolder::filePath).forEach(assertFileExist(assertions));
            assertions.assertAll();
            return this;
        }
public JHipsterModuleAsserter hasPrefixedFiles(String prefix, String... files){
            assertThat(files).as("Can't check null files for a module").isNotNull();
            String[] sourceFiles = Stream.of(files).map( file -> prefix + SLASH + file).toArray(String[]::new);
            return hasFiles(sourceFiles);
        }
public JHipsterModuleAsserter hasJavaTests(String... files){
            return hasPrefixedFiles("src/test/java", files);
        }
/**************TEST HELPER METHOD END*************/


